		if (unnamed.length > 0) {
			directions.push(
				listed(
					"Captured as linked_work_items/<n>.md but not named by a closing keyword, the title, the branch or a provider closing link: ",
					unnamed.map((n) => `#${n}`),
				),
			);
		}
